  // Returns the audit logger config Json wrapped under its type name, or a
  // null Json on failure (after recording a validation error).
  auto parse_config = [&](absl::string_view name,
                          Json json_config) -> Json {
    auto result = AuditLoggerRegistry::ParseConfig(name, json_config);
    if (!result.ok()) {
      errors->AddError(result.status().message());
      return Json();
    }
    return Json::FromObject(
        {{std::string(name), std::move(json_config)}});
  };
  return MatchMutable(
      &extension->value,
      // Check for registered audit logger type.
      [&](absl::string_view* serialized_value) -> Json {
        auto config_factory_it =
            audit_logger_config_factories_.find(extension->type);
        if (config_factory_it == audit_logger_config_factories_.end()) {
          return Json();
        }
        return parse_config(
            config_factory_it->second->name(),
            Json::FromObject(
                config_factory_it->second->ConvertXdsAuditLoggerConfig(
                    context, *serialized_value, errors)));
      },
      // Check for custom audit logger type.
      [&](Json* json) -> Json {
        if (!AuditLoggerRegistry::FactoryExists(extension->type)) {
          return Json();
        }
        return parse_config(extension->type, std::move(*json));
      });
}

